content:
A \textbf{set} is an unordered collection of distinct objects, called the
\textbf{elements} (or \textit{members}) of the set.

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Notation:}}
\begin{itemize}[leftmargin=1.5em]
    \item Sets are denoted by \textbf{capital letters}: $A, B, C, S, \ldots$
    \item Elements are denoted by \textbf{lowercase letters}: $a, b, x, y, \ldots$
    \item $a \in A$ means ``$a$ \textbf{is an element of} $A$'' (read: ``$a$ is in $A$'')
    \item $a \notin A$ means ``$a$ \textbf{is not an element of} $A$''
    \item Sets are \textbf{unordered}: $\{1,2,3\} = \{3,1,2\} = \{2,3,1\}$
    \item Elements are \textbf{distinct}: $\{1,1,2\}$ is the same set as $\{1,2\}$
\end{itemize}

\vspace{0.5cm}

Let $A$ be the set of odd positive integers less than 10.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Roster method:}
\[
    A = \{1,\, 3,\, 5,\, 7,\, 9\}
\]

\textbf{Set-builder notation:}
\[
    A = \{x \in \mathbb{Z}^+ \mid x \text{ is odd and } x < 10\}
\]
or equivalently:
\[
    A = \{x \mid x = 2k-1,\; k \in \mathbb{Z}^+,\; x < 10\}
\]

\textbf{Cardinality:} $|A| = 5$ \quad (the set has 5 elements)

\vspace{0.3cm}
\textbf{Membership checks:}
\begin{itemize}[leftmargin=1.5em]
    \item $3 \in A$ \hfill \textcolor{darkgreen}{\checkmark\ True}
    \item $4 \in A$ \hfill \textcolor{red}{$\times$\ False}
    \item $11 \in A$ \hfill \textcolor{red}{$\times$\ False} (11 is not less than 10)
\end{itemize}

\vspace{0.2cm}
\textit{(Past Paper 2022 Q1(viii) directly asks: ``Let $A$ be the set of odd positive
integers less than 10. Then $|A| = ?$'' Answer: $|A| = 5$.)}

\vspace{0.5cm}

\textbf{Empty Set:} The set with no elements, written $\emptyset$ or $\{\}$.
\[
    \emptyset = \{\} \qquad |\emptyset| = 0
\]

\textbf{Universal Set:} The set $U$ containing all objects under consideration
in a particular context (the ``universe of discourse'').

\vspace{0.3cm}
\textbf{Singleton Set:} A set with exactly one element, e.g.\ $\{5\}$ or $\{\emptyset\}$.

\vspace{0.4cm}
\textcolor{accentorange}{\textbf{Critical Warning:}}
\begin{itemize}[leftmargin=1.5em]
    \item $\emptyset \neq \{\emptyset\}$ --- the empty set has 0 elements;
          the set $\{\emptyset\}$ has \textbf{1} element (the empty set itself).
    \item $0 \neq \emptyset$ --- zero is a number, not a set.
    \item $\{0\} \neq \emptyset$ --- $\{0\}$ is a set containing the number zero.
\end{itemize}

\vspace{0.5cm}

The \textbf{cardinality} of a set $A$, written $|A|$ or $\#A$, is the
\textbf{number of distinct elements} in $A$.

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|l|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Set} & \textbf{Cardinality} \\
\hline
$\emptyset$ & $0$ \\
\hline
$\{a, b, c\}$ & $3$ \\
\hline
$\{1, 1, 2, 3\}$ & $3$ \quad (duplicates don't count) \\
\hline
$\{\emptyset\}$ & $1$ \\
\hline
$\{\emptyset, \{1\}, \{1,2\}\}$ & $3$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
A set is called \textbf{finite} if its cardinality is a non-negative integer.
Otherwise it is \textbf{infinite} (e.g.\ $\mathbb{Z}$, $\mathbb{R}$).

\vspace{0.5cm}

The \textbf{power set} of a set $A$, written $\mathcal{P}(A)$ or $2^A$,
is the set of \textbf{all subsets} of $A$, including $\emptyset$ and $A$ itself.
\[
    \mathcal{P}(A) = \{S \mid S \subseteq A\}
\]

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Formula:}}
\[
    \text{If } |A| = n, \text{ then } |\mathcal{P}(A)| = 2^n
\]

\vspace{0.2cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Why $2^n$?}} Each element of $A$ is
\textit{either included or excluded} from a subset --- 2 choices per element,
$n$ elements, so $2 \times 2 \times \cdots \times 2 = 2^n$ subsets in total.

\vspace{0.5cm}

Find the power set of $A = \{1, 3, 5\}$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
$|A| = 3$, so $|\mathcal{P}(A)| = 2^3 = 8$ subsets.

\vspace{0.3cm}
\textbf{Systematic enumeration} (by number of elements in each subset):

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|c|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Subset Size} & \textbf{Subsets} \\
\hline
0 elements & $\emptyset$ \\
\hline
1 element & $\{1\},\quad \{3\},\quad \{5\}$ \\
\hline
2 elements & $\{1,3\},\quad \{1,5\},\quad \{3,5\}$ \\
\hline
3 elements & $\{1,3,5\}$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
Therefore:
\[
    \boxed{\mathcal{P}(A) = \bigl\{\,\emptyset,\; \{1\},\; \{3\},\; \{5\},\;
    \{1,3\},\; \{1,5\},\; \{3,5\},\; \{1,3,5\}\,\bigr\}}
\]

\textbf{Verification:} $|\mathcal{P}(A)| = 8 = 2^3$ \textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

What is the power set of the empty set $\emptyset$?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
$|\emptyset| = 0$, so $|\mathcal{P}(\emptyset)| = 2^0 = 1$.

The only subset of the empty set is the empty set itself.
\[
    \boxed{\mathcal{P}(\emptyset) = \{\emptyset\}}
\]

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Common Mistake:}} Students often write
$\mathcal{P}(\emptyset) = \emptyset$ (the empty set). This is \textcolor{red}{wrong}.
$\mathcal{P}(\emptyset)$ is \textbf{not empty} --- it contains one element:
the empty set. Always remember:
\[
    |\mathcal{P}(\emptyset)| = 2^0 = 1 \neq 0
\]

\vspace{0.5cm}

An \textbf{ordered pair} $(a, b)$ is a pair of elements where order matters:
$(a,b) \neq (b,a)$ in general.

\vspace{0.3cm}
The \textbf{Cartesian product} of sets $A$ and $B$, written $A \times B$,
is the set of all ordered pairs $(a,b)$ where $a \in A$ and $b \in B$:
\[
    A \times B = \{(a,b) \mid a \in A \text{ and } b \in B\}
\]

\vspace{0.3cm}
\textbf{Cardinality:} $|A \times B| = |A| \cdot |B|$

\vspace{0.3cm}
\textbf{Example:} If $A = \{1,2\}$ and $B = \{x, y\}$ then:
\[
    A \times B = \{(1,x),\,(1,y),\,(2,x),\,(2,y)\}
    \qquad |A \times B| = 4
\]

\vspace{0.2cm}
\textcolor{accentorange}{\textbf{Note:}} $A \times B \neq B \times A$ in general
(order of pairs is reversed).

\vspace{0.5cm}

Let $A = \{0, 1\}$ and $B = \{a, b, c\}$.

\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item Find $A \times B$.
    \item Find $B \times A$.
    \item Is $A \times B = B \times A$?
    \item How many subsets does $A \times B$ have?
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)}
\[
    A \times B = \{(0,a),\,(0,b),\,(0,c),\,(1,a),\,(1,b),\,(1,c)\}
    \qquad |A \times B| = 6
\]

\textbf{(b)}
\[
    B \times A = \{(a,0),\,(a,1),\,(b,0),\,(b,1),\,(c,0),\,(c,1)\}
    \qquad |B \times A| = 6
\]

\textbf{(c)} $A \times B \neq B \times A$ because, for example, $(0,a) \in A \times B$
but $(0,a) \notin B \times A$ (since $0 \notin B$). \textcolor{red}{Not equal.}

\textbf{(d)} $|A \times B| = 6$, so $|\mathcal{P}(A \times B)| = 2^6 = \boxed{64}$ subsets.

\vspace{0.5cm}

Express each set using set-builder notation, then find its cardinality:
\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item The set of all positive integers less than or equal to 100
          that are divisible by both 3 and 5.
    \item The set of all real solutions to $x^2 - 5x + 6 = 0$.
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} A number is divisible by both 3 and 5 iff it is divisible by $\text{lcm}(3,5) = 15$.
\[
    A = \{x \in \mathbb{Z}^+ \mid x \leq 100 \text{ and } 15 \mid x\}
    = \{15, 30, 45, 60, 75, 90\}
\]
\[
    |A| = \left\lfloor \frac{100}{15} \right\rfloor = 6
\]

\textbf{(b)} Solve $x^2 - 5x + 6 = 0$:
\[
    (x-2)(x-3) = 0 \implies x = 2 \text{ or } x = 3
\]
\[
    B = \{x \in \mathbb{R} \mid x^2 - 5x + 6 = 0\} = \{2, 3\}
    \qquad |B| = 2
\]

\vspace{0.5cm}




\begin{center}
