\vspace{0.5cm}

Let $A = \{1, 2, 3\}$ and $R = \{(1,1),(1,2),(2,3),(3,1)\}$.

\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item Write $R$ as a set of ordered pairs.
    \item Construct the relation matrix $M_R$.
    \item Describe the digraph.
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} $R = \{(1,1),(1,2),(2,3),(3,1)\}$ --- already in set form.

\vspace{0.3cm}
\textbf{(b) Relation matrix:} Rows and columns ordered $1, 2, 3$.

\[
    M_R = \begin{pmatrix}
        1 & 1 & 0 \\
        0 & 0 & 1 \\
        1 & 0 & 0
    \end{pmatrix}
\]

Entry $(i,j) = 1$ iff $(i,j) \in R$.

\vspace{0.3cm}
\textbf{(c) Digraph:}

\begin{center}
\begin{tikzpicture}[
    vertex/.style={circle, draw=primaryblue, fill=primaryblue!15,
                   minimum size=0.8cm, font=\small\bfseries},
    arrow/.style={->, thick, color=primaryblue}
]
\node[vertex] (1) at (0,  1.5) {1};
\node[vertex] (2) at (2,  0)   {2};
\node[vertex] (3) at (-2, 0)   {3};

\draw[arrow] (1) to[loop above] (1);           % (1,1)
\draw[arrow] (1) -- (2);                        % (1,2)
\draw[arrow] (2) -- (3);                        % (2,3)
\draw[arrow] (3) -- (1);                        % (3,1)
\end{tikzpicture}
\end{center}

\vspace{0.5cm}

A relation $R$ on set $A$ is \textbf{reflexive} if every element is related
to \textbf{itself}:
\[
    R \text{ is reflexive} \iff \forall a \in A,\; (a,a) \in R
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Recognition Tips:}}
\begin{itemize}[leftmargin=1.5em]
    \item In the \textbf{matrix}: all diagonal entries ($M[i][i]$) are \textbf{1}.
    \item In the \textbf{digraph}: every vertex has a \textbf{loop}.
    \item To \textbf{disprove}: find any $a \in A$ with $(a,a) \notin R$.
\end{itemize}

\vspace{0.5cm}

A relation $R$ on set $A$ is \textbf{symmetric} if whenever $(a,b) \in R$,
then $(b,a) \in R$ as well:
\[
    R \text{ is symmetric} \iff \forall a,b \in A,\;
    [(a,b) \in R \rightarrow (b,a) \in R]
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Recognition Tips:}}
\begin{itemize}[leftmargin=1.5em]
    \item In the \textbf{matrix}: $M$ is \textbf{symmetric} ($M = M^T$),
          i.e.\ $M[i][j] = M[j][i]$ for all $i, j$.
    \item In the \textbf{digraph}: for every directed edge $a \to b$,
          there is also $b \to a$ (edges come in \textbf{pairs}).
    \item The empty relation $\emptyset$ is symmetric (vacuously).
\end{itemize}

\vspace{0.5cm}

Let $R$ be a relation on $A = \{a_1, \ldots, a_n\}$ with matrix $M_R$. Then:

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Property} & \textbf{Matrix Condition} \\
\hline
Reflexive & All diagonal entries are 1: $M[i][i] = 1$ for all $i$ \\
\hline
Irreflexive & All diagonal entries are 0: $M[i][i] = 0$ for all $i$ \\
\hline
Symmetric & $M = M^T$, i.e.\ $M[i][j] = M[j][i]$ for all $i,j$ \\
\hline
Antisymmetric & $M[i][j] = 1$ and $i \neq j$ $\Rightarrow$ $M[j][i] = 0$ \\
\hline
Transitive & $M^2_R \leq M_R$ (Boolean matrix product: if $(M_R^2)[i][j]=1$ then $M_R[i][j]=1$) \\
\hline
\end{tabular}
\end{center}

\vspace{0.5cm}

For each relation on $\{3,4,5,6\}$, determine whether it is reflexive,
symmetric, antisymmetric, and transitive.

\vspace{0.2cm}
\textbf{(a)} $R_1 = \{(3,3),(3,4),(3,6),(5,4),(5,5),(5,6)\}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.2cm}
\textbf{Reflexive?} Need $(3,3),(4,4),(5,5),(6,6) \in R_1$.
$(4,4) \notin R_1$ and $(6,6) \notin R_1$. \textcolor{red}{$\times$ Not reflexive.}

\textbf{Symmetric?} $(3,4) \in R_1$ but $(4,3) \notin R_1$.
\textcolor{red}{$\times$ Not symmetric.}

\textbf{Antisymmetric?} Check all pairs: no pair $(a,b)$ and $(b,a)$ with $a \neq b$ exist.
\textcolor{darkgreen}{\checkmark\ Antisymmetric.}

\textbf{Transitive?} Check: $(3,4) \in R_1$ --- need $(4,?)$ pairs. No $(4,x) \in R_1$,
so no violation from $(3,4)$. $(3,6) \in R_1$ --- no $(6,x)$ pairs.
$(5,4),(5,6)$ --- no $(4,x)$ or $(6,x)$. $(3,3) \in R_1$: $(3,3)+(3,4) \Rightarrow$ need $(3,4)$ \textcolor{darkgreen}{\checkmark};
$(3,3)+(3,6) \Rightarrow$ need $(3,6)$ \textcolor{darkgreen}{\checkmark}.
$(5,5)+(5,4) \Rightarrow$ need $(5,4)$ \textcolor{darkgreen}{\checkmark}.
$(5,5)+(5,6) \Rightarrow$ need $(5,6)$ \textcolor{darkgreen}{\checkmark}.
\textcolor{darkgreen}{\checkmark\ Transitive.}

\vspace{0.5cm}
\textbf{(b)} $R_2 = \{(3,3),(3,4),(4,3),(4,4),(5,5),(6,6)\}$

\vspace{0.3cm}
\textbf{Reflexive?} $(3,3),(4,4),(5,5),(6,6) \in R_2$. \textcolor{darkgreen}{\checkmark\ Reflexive.}

\textbf{Symmetric?} $(3,4) \in R_2$ and $(4,3) \in R_2$. All other non-diagonal pairs absent.
\textcolor{darkgreen}{\checkmark\ Symmetric.}

\textbf{Antisymmetric?} $(3,4) \in R_2$ and $(4,3) \in R_2$ with $3 \neq 4$.
\textcolor{red}{$\times$ Not antisymmetric.}

\textbf{Transitive?}
$(3,4)+(4,3) \Rightarrow$ need $(3,3)$ \textcolor{darkgreen}{\checkmark};
$(4,3)+(3,4) \Rightarrow$ need $(4,4)$ \textcolor{darkgreen}{\checkmark};
$(3,4)+(4,4) \Rightarrow$ need $(3,4)$ \textcolor{darkgreen}{\checkmark};
$(4,3)+(3,3) \Rightarrow$ need $(4,3)$ \textcolor{darkgreen}{\checkmark}.
\textcolor{darkgreen}{\checkmark\ Transitive.}

\vspace{0.5cm}
\textbf{(c)} $R_3 = \{(3,4),(4,5),(5,6)\}$

\vspace{0.3cm}
\textbf{Reflexive?} $(3,3) \notin R_3$.
\textcolor{red}{$\times$ Not reflexive.}

\textbf{Symmetric?} $(3,4) \in R_3$ but $(4,3) \notin R_3$.
\textcolor{red}{$\times$ Not symmetric.}

\textbf{Antisymmetric?} No pair $(a,b)$ and $(b,a)$ with $a \neq b$ both present.
\textcolor{darkgreen}{\checkmark\ Antisymmetric.}

\textbf{Transitive?} $(3,4)+(4,5) \Rightarrow$ need $(3,5)$. $(3,5) \notin R_3$.
\textcolor{red}{$\times$ Not transitive.}

\vspace{0.5cm}
\textbf{(d)} $R_4 = \{(3,5),(3,6),(4,5),(4,6),(5,3),(5,5)\}$

\vspace{0.3cm}
\textbf{Reflexive?} $(3,3) \notin R_4$.
\textcolor{red}{$\times$ Not reflexive.}

\textbf{Symmetric?} $(3,5) \in R_4$ and $(5,3) \in R_4$ \textcolor{darkgreen}{\checkmark}.
But $(3,6) \in R_4$ and $(6,3) \notin R_4$.
\textcolor{red}{$\times$ Not symmetric.}

\textbf{Antisymmetric?} $(3,5) \in R_4$ and $(5,3) \in R_4$ with $3 \neq 5$.
\textcolor{red}{$\times$ Not antisymmetric.}

\textbf{Transitive?} $(5,3)+(3,5) \Rightarrow$ need $(5,5)$ \textcolor{darkgreen}{\checkmark}.
$(5,3)+(3,6) \Rightarrow$ need $(5,6)$. $(5,6) \notin R_4$.
\textcolor{red}{$\times$ Not transitive.}

