\vspace{0.5cm}

For each relation on $\{1,2,3,4\}$, determine which properties hold:
reflexive, symmetric, transitive.

\vspace{0.2cm}
\textbf{(i)} $R_1 = \{(2,2),(2,3),(2,4),(3,2),(3,3),(3,4)\}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Reflexive?} $(1,1) \notin R_1$ and $(4,4) \notin R_1$.
\textcolor{red}{$\times$ Not reflexive.}

\textbf{Symmetric?} $(2,4) \in R_1$ but $(4,2) \notin R_1$.
\textcolor{red}{$\times$ Not symmetric.}

\textbf{Transitive?} $(3,2)+(2,3) \Rightarrow (3,3)$ \textcolor{darkgreen}{\checkmark};
$(3,2)+(2,4) \Rightarrow (3,4)$ \textcolor{darkgreen}{\checkmark};
$(2,3)+(3,2) \Rightarrow (2,2)$ \textcolor{darkgreen}{\checkmark};
$(2,3)+(3,4) \Rightarrow (2,4)$ \textcolor{darkgreen}{\checkmark};
$(2,2)+(2,3) \Rightarrow (2,3)$ \textcolor{darkgreen}{\checkmark};
$(3,3)+(3,4) \Rightarrow (3,4)$ \textcolor{darkgreen}{\checkmark}.
\textcolor{darkgreen}{\checkmark\ Transitive.}

\vspace{0.4cm}
\textbf{(ii)} $R_2 = \{(1,1),(1,2),(2,1),(2,2),(3,3),(4,4)\}$

\textbf{Reflexive?} All of $(1,1),(2,2),(3,3),(4,4) \in R_2$.
\textcolor{darkgreen}{\checkmark\ Reflexive.}

\textbf{Symmetric?} $(1,2) \in R_2$ and $(2,1) \in R_2$. All others symmetric.
\textcolor{darkgreen}{\checkmark\ Symmetric.}

\textbf{Transitive?} $(1,2)+(2,1) \Rightarrow (1,1)$ \textcolor{darkgreen}{\checkmark};
$(2,1)+(1,2) \Rightarrow (2,2)$ \textcolor{darkgreen}{\checkmark};
$(1,2)+(2,2) \Rightarrow (1,2)$ \textcolor{darkgreen}{\checkmark}.
\textcolor{darkgreen}{\checkmark\ Transitive.}

\vspace{0.4cm}
\textbf{(iii)} $R_3 = \emptyset$ (empty relation)

\textbf{Reflexive?} $(1,1) \notin \emptyset$.
\textcolor{red}{$\times$ Not reflexive.}

\textbf{Symmetric?} Vacuously true --- there are no pairs $(a,b) \in R_3$ to check.
\textcolor{darkgreen}{\checkmark\ Symmetric (vacuously).}

\textbf{Transitive?} Vacuously true.
\textcolor{darkgreen}{\checkmark\ Transitive (vacuously).}

\vspace{0.4cm}
\textbf{(iv)} $R_4 = \{(1,1),(2,2),(3,3),(4,4)\}$ (equality relation)

\textbf{Reflexive?} All $(a,a) \in R_4$.
\textcolor{darkgreen}{\checkmark\ Reflexive.}

\textbf{Symmetric?} Only pairs of form $(a,a)$ --- symmetric trivially.
\textcolor{darkgreen}{\checkmark\ Symmetric.}

\textbf{Transitive?} $(a,a)+(a,a) \Rightarrow (a,a)$ \textcolor{darkgreen}{\checkmark}.
\textcolor{darkgreen}{\checkmark\ Transitive.}

\vspace{0.4cm}
\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Relation} & \textbf{Reflexive} & \textbf{Symmetric} & \textbf{Transitive} \\
\hline
$R_1$ & \textcolor{red}{No}  & \textcolor{red}{No}  & \textcolor{darkgreen}{Yes} \\
\hline
$R_2$ & \textcolor{darkgreen}{Yes} & \textcolor{darkgreen}{Yes} & \textcolor{darkgreen}{Yes} \\
\hline
$R_3 = \emptyset$ & \textcolor{red}{No} & \textcolor{darkgreen}{Yes} & \textcolor{darkgreen}{Yes} \\
\hline
$R_4$ (equality) & \textcolor{darkgreen}{Yes} & \textcolor{darkgreen}{Yes} & \textcolor{darkgreen}{Yes} \\
\hline
\end{tabular}
\end{center}

\vspace{0.5cm}

Let $A = \{0,1,2,5\}$. Analyse each of $R$, $S$, $T$:

$R = \{(0,0),(0,1),(0,5),(1,0),(1,1),(2,2),(5,0),(5,5)\}$

$S = \{(0,0),(0,2),(0,5),(2,5)\}$

$T = \{(0,1),(2,5)\}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Relation $R$:}

\textit{Reflexive?} $(0,0),(1,1),(2,2),(5,5) \in R$.
\textcolor{darkgreen}{\checkmark\ Reflexive.}

\textit{Symmetric?} $(0,1) \in R$ and $(1,0) \in R$ \textcolor{darkgreen}{\checkmark};
$(0,5) \in R$ and $(5,0) \in R$ \textcolor{darkgreen}{\checkmark};
all self-loops symmetric.
\textcolor{darkgreen}{\checkmark\ Symmetric.}

\textit{Transitive?} $(1,0)+(0,1) \Rightarrow (1,1)$ \textcolor{darkgreen}{\checkmark};
$(1,0)+(0,5) \Rightarrow (1,5)$. $(1,5) \notin R$.
\textcolor{red}{$\times$ Not transitive.}

\vspace{0.3cm}
\textbf{Relation $S$:}

\textit{Reflexive?} $(1,1) \notin S$.
\textcolor{red}{$\times$ Not reflexive.}

\textit{Symmetric?} $(0,2) \in S$ but $(2,0) \notin S$.
\textcolor{red}{$\times$ Not symmetric.}

\textit{Transitive?} $(0,2)+(2,5) \Rightarrow (0,5)$ \textcolor{darkgreen}{\checkmark};
$(0,0)+(0,2) \Rightarrow (0,2)$ \textcolor{darkgreen}{\checkmark};
$(0,0)+(0,5) \Rightarrow (0,5)$ \textcolor{darkgreen}{\checkmark}.
No other composable pairs.
\textcolor{darkgreen}{\checkmark\ Transitive.}

\vspace{0.3cm}
\textbf{Relation $T$:}

\textit{Reflexive?} $(0,0) \notin T$.
\textcolor{red}{$\times$ Not reflexive.}

\textit{Symmetric?} $(0,1) \in T$ but $(1,0) \notin T$.
\textcolor{red}{$\times$ Not symmetric.}

\textit{Transitive?} No two pairs in $T$ are composable (no $x$ such that
$(0,x),(x,?) \in T$ with both present).
\textcolor{darkgreen}{\checkmark\ Transitive (vacuously).}

