$R$ & \textcolor{darkgreen}{Yes} & \textcolor{darkgreen}{Yes} & \textcolor{red}{No} \\
\hline
$S$ & \textcolor{red}{No}  & \textcolor{red}{No}  & \textcolor{darkgreen}{Yes} \\
\hline
$T$ & \textcolor{red}{No}  & \textcolor{red}{No}  & \textcolor{darkgreen}{Yes} \\
