\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Master Table of Properties:}}

\vspace{0.2cm}
\begin{center}
\begin{tabular}{|l|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Property} & \textbf{Definition} & \textbf{Matrix} & \textbf{Digraph} \\
\hline
Reflexive     & $(a,a)\in R\;\forall a$         & Diagonal all 1s & Loop at every vertex \\
\hline
Irreflexive   & $(a,a)\notin R\;\forall a$      & Diagonal all 0s & No loops \\
\hline
Symmetric     & $(a,b)\Rightarrow(b,a)$          & $M=M^T$         & Edges in pairs \\
\hline
Antisymmetric & $(a,b)\land(b,a)\Rightarrow a=b$ & No sym.\ off-diag 1s & No 2-cycles \\
\hline
Transitive    & $(a,b)\land(b,c)\Rightarrow(a,c)$ & $M^2 \leq M$  & Path$\Rightarrow$edge \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Common Traps:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Antisymmetric $\neq$ not symmetric.}
          A relation can be both (e.g.\ $\{(1,1),(2,2)\}$) or neither
          (e.g.\ $\{(1,2),(2,1),(1,3)\}$).
    \item \textbf{Empty relation} $\emptyset$ is symmetric, antisymmetric,
          and transitive (all vacuously), but NOT reflexive.
    \item \textbf{Transitivity} --- always check \textit{all} composable pairs.
          Missing even one pair $(a,b),(b,c)$ with $(a,c)\notin R$ breaks transitivity.
    \item \textbf{Vacuous truth} --- if no pair $(a,b)$ exists with $a \neq b$,
          the relation is automatically symmetric and antisymmetric.
\end{itemize}

