\textcolor{primaryblue}{\textbf{\faLightbulb\ Section 2.4 Summary --- Equivalence Relations \& Partitions}}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ The Big Picture:}}

\vspace{0.2cm}
\begin{center}
\begin{tabular}{|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Concept} & \textbf{Key Fact} \\
\hline
Equivalence relation & Must be Reflexive + Symmetric + Transitive \\
\hline
Equivalence class $[a]$ & All elements related to $a$; $a \in [a]$ always \\
\hline
$[a] = [b]$ & iff $(a,b) \in R$ \\
\hline
$[a] \cap [b]$ & Either $= [a]=[b]$ or $= \emptyset$ \\
\hline
Partition & Disjoint, non-empty subsets covering $A$ \\
\hline
Correspondence & Equivalence relations $\longleftrightarrow$ Partitions \\
\hline
Congruence mod $n$ & Gives $n$ equivalence classes: $[0],[1],\ldots,[n-1]$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Step-by-Step: Analysing an Equivalence Relation}}
\begin{enumerate}[leftmargin=2em]
    \item Check \textbf{reflexive}: is $(a,a) \in R$ for every $a \in A$?
    \item Check \textbf{symmetric}: for every $(a,b) \in R$, is $(b,a) \in R$?
    \item Check \textbf{transitive}: for every $(a,b),(b,c) \in R$,
          is $(a,c) \in R$?
    \item If all three hold: find the equivalence classes by grouping related elements.
    \item Verify: classes are disjoint and cover $A$.
\end{enumerate}

