\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Step 1: List all divisibility pairs} ($a \mid b$ with $a \neq b$):
\[
    1\mid 2,\; 1\mid 3,\; 1\mid 4,\; 1\mid 6,\; 1\mid 12,\;
    2\mid 4,\; 2\mid 6,\; 2\mid 12,\; 3\mid 6,\; 3\mid 12,\;
    4\mid 12,\; 6\mid 12
\]

\textbf{Step 2: Remove transitive edges.}
$1 \mid 4$ is implied by $1\mid 2$ and $2\mid 4$, so remove direct $1\to 4$.
Similarly remove $1\to 6$, $1\to 12$, $2\to 12$, $3\to 12$.

\textbf{Step 3: Draw upward edges only (no arrows, no loops).}

